// Pecah 1 item multi-binary jadi N item, rename binary ke "data",
// deteksi format via magic bytes + ekstensi.

const items = $input.all();
const firstBody = (items[0] && items[0].json && items[0].json.body) || {};
const resultId = firstBody.result_id || null;
const filePath = firstBody.file_path || null;
const locale = firstBody.locale === 'id' ? 'id' : 'en';
const controlCode = firstBody.control_code || '';
const controlTitle = firstBody.control_title || '';
const controlRequirement = firstBody.control_requirement || '';

const SIGS = [
  { hex: '25504446', cat: 'PDF' },
  { hex: 'FFD8FF',   cat: 'IMAGE' },
  { hex: '89504E47', cat: 'IMAGE' },
  { hex: '47494638', cat: 'IMAGE' },
  { hex: '424D',     cat: 'IMAGE' },
  { hex: '49492A00', cat: 'IMAGE' },
  { hex: '4D4D002A', cat: 'IMAGE' },
];
const ZIP = '504B0304';
const OLE = 'D0CF11E0';

const EXT_MAP = {
  xlsx: 'SPREADSHEET', xlsm: 'SPREADSHEET', ods: 'SPREADSHEET', csv: 'SPREADSHEET',
  docx: 'WORD', doc: 'LEGACY_DOC', pdf: 'PDF',
  jpg: 'IMAGE', jpeg: 'IMAGE', png: 'IMAGE', webp: 'IMAGE',
  bmp: 'IMAGE', tif: 'IMAGE', tiff: 'IMAGE', gif: 'IMAGE',
};

const MIME_IMG = {
  jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp',
  bmp: 'image/bmp', tif: 'image/tiff', tiff: 'image/tiff', gif: 'image/gif',
};

const MAX_BYTES = 20 * 1024 * 1024;
const out = [];
let seq = 0;

for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary || {};

  for (const key of Object.keys(bin)) {
    const meta = bin[key];
    const fileName = meta.fileName || key;
    const ext = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';

    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    const head = buf.subarray(0, 8).toString('hex').toUpperCase();
    const warnings = [];

    let sigCat = null;
    if (head.startsWith(ZIP)) sigCat = 'ZIP';
    else if (head.startsWith(OLE)) sigCat = 'OLE';
    else {
      for (const s of SIGS) {
        if (head.startsWith(s.hex)) { sigCat = s.cat; break; }
      }
    }

    let category;
    if (sigCat === 'ZIP') {
      if (ext === 'docx') category = 'WORD';
      else if (['xlsx', 'xlsm', 'ods'].includes(ext)) category = 'SPREADSHEET';
      else { category = 'UNSUPPORTED'; warnings.push('zip_container_unknown_ext'); }
    } else if (sigCat === 'OLE') {
      if (ext === 'doc') category = 'LEGACY_DOC';
      else { category = 'UNSUPPORTED'; warnings.push('legacy_ole_' + (ext || 'unknown')); }
    } else if (sigCat) {
      category = sigCat;
    } else if (ext === 'csv' || ext === 'txt') {
      category = 'SPREADSHEET';
    } else {
      category = 'UNSUPPORTED';
      warnings.push('unknown_signature');
    }

    const extCat = EXT_MAP[ext];
    if (extCat && category !== 'UNSUPPORTED' && extCat !== category) {
      warnings.push('ext_signature_mismatch:' + ext + '_vs_' + category);
    }
    if (buf.length === 0) { category = 'UNSUPPORTED'; warnings.push('empty_file'); }
    if (buf.length > MAX_BYTES) { category = 'UNSUPPORTED'; warnings.push('file_too_large'); }

    seq += 1;
    out.push({
      json: {
        file_id: 'f' + String(seq).padStart(3, '0'),
        file_name: fileName,
        file_ext: ext,
        file_size: buf.length,
        signature: head,
        file_category: category,
        mime_type: MIME_IMG[ext] || meta.mimeType || 'application/octet-stream',
        result_id: resultId,
        file_path: filePath,
        locale: locale,
        control_code: controlCode,
        control_title: controlTitle,
        control_requirement: controlRequirement,
        warnings,
      },
      binary: { data: meta },
    });
  }
}

if (out.length === 0) throw new Error('Tidak ada file terdeteksi pada input.');
return out;

const items = $input.all();
const groups = new Map();

for (let i = 0; i < items.length; i++) {
  const src = $('Fan-out & Detect').itemMatching(i).json;
  if (!groups.has(src.file_id)) groups.set(src.file_id, { src, rows: [] });
  groups.get(src.file_id).rows.push(items[i].json);
}

function toMarkdown(rows) {
  if (!rows.length) return '';
  const cols = [...new Set(rows.flatMap(r => Object.keys(r)))];
  const esc = v => (v === null || v === undefined ? '' : String(v).replace(/\|/g, '\\|').replace(/\r?\n/g, ' '));
  const lines = [];
  lines.push('| ' + cols.join(' | ') + ' |');
  lines.push('| ' + cols.map(() => '---').join(' | ') + ' |');
  for (const r of rows) lines.push('| ' + cols.map(c => esc(r[c])).join(' | ') + ' |');
  return lines.join('\n');
}

const out = [];
for (const g of groups.values()) {
  out.push({ json: {
    file_id: g.src.file_id, file_name: g.src.file_name,
    file_category: 'SPREADSHEET', content_mode: 'text',
    extraction_method: g.src.file_ext === 'csv' ? 'native_csv' : 'native_xlsx',
    text: '=== ' + g.src.file_name + ' ===\n' + toMarkdown(g.rows),
    visual_description: '', page_count: 1, row_count: g.rows.length,
    result_id: g.src.result_id || null, file_path: g.src.file_path || null, locale: g.src.locale || 'en',
    control_code: g.src.control_code || '', control_title: g.src.control_title || '', control_requirement: g.src.control_requirement || '',
    warnings: g.src.warnings || [],
  }});
}
return out;

const items = $input.all();

return items.map((item, i) => {
  const src = $('Fan-out & Detect').itemMatching(i).json;
  const j = item.json || {};
  return { json: {
    file_id: src.file_id, file_name: src.file_name,
    file_category: 'PDF', content_mode: 'text',
    extraction_method: 'native_pdf',
    text: (j.text || '').trim(), visual_description: '',
    page_count: j.numpages || 1,
    result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
    control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
    warnings: src.warnings || [],
  }};
});

const MODEL = 'thinkingmachines/inkling-small';

const PROMPT_ID = [
  'Tugasmu HANYA menyalin teks yang terlihat pada gambar dokumen ini ke dalam markdown.',
  '',
  'Aturan wajib:',
  '- Salin persis. Jangan meringkas, menafsirkan, memperbaiki, atau menambah apa pun.',
  '- Pertahankan urutan baca asli (atas ke bawah, kiri ke kanan).',
  '- Tabel ditulis ulang sebagai tabel markdown.',
  '- Angka, tanggal, nomor dokumen, dan kode disalin persis seperti tertulis.',
  '- Bagian yang tidak terbaca ditulis [tidak terbaca].',
  '- DILARANG mendeskripsikan isi atau tampilan gambar.',
  '- Jika gambar tidak memuat teks sama sekali, keluarkan PERSIS satu baris ini dan tidak ada yang lain: NO_TEXT_FOUND',
  '',
  'Keluarkan HANYA hasil salinan, tanpa kalimat pembuka atau penutup.',
].join('\n');

const PROMPT_EN = [
  'Your task is ONLY to transcribe the text visible in this document image into markdown.',
  '',
  'Mandatory rules:',
  '- Copy exactly. Do not summarize, interpret, correct, or add anything.',
  '- Preserve the original reading order (top to bottom, left to right).',
  '- Rewrite tables as markdown tables.',
  '- Numbers, dates, document numbers, and codes must be copied exactly as written.',
  '- Illegible sections must be written as [illegible].',
  '- You are FORBIDDEN from describing the content or appearance of the image.',
  '- If the image contains no text at all, output EXACTLY this one line and nothing else: NO_TEXT_FOUND',
  '',
  'Output ONLY the transcription, with no opening or closing remarks.',
].join('\n');

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = $('Fan-out & Detect').itemMatching(i).json;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const dataUri = 'data:' + src.mime_type + ';base64,' + buf.toString('base64');
  const PROMPT = (src.locale === 'id') ? PROMPT_ID : PROMPT_EN;

  out.push({ json: {
    file_id: src.file_id, file_name: src.file_name,
    file_category: src.file_category, mime_type: src.mime_type,
    result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
    control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
    warnings: src.warnings || [], data_uri: dataUri,
    baseten_payload: {
      model: MODEL, temperature: 0, max_tokens: 8000,
      messages: [{ role: 'user', content: [
        { type: 'text', text: PROMPT },
        { type: 'image_url', image_url: { url: dataUri } },
      ]}],
    },
  }});
}
return out;

const MIN_TEXT = 50;
const items = $input.all();

return items.map((item, i) => {
  const src = $('Prepare OCR Payload').itemMatching(i).json;
  const raw = item.json && item.json.choices && item.json.choices[0]
    ? item.json.choices[0].message.content : '';

  let rawText = '';
  if (typeof raw === 'string') rawText = raw;
  else if (Array.isArray(raw)) rawText = raw.map(p => p.text || '').join('\n');
  rawText = rawText.trim();

  const noTextFound = rawText === '' || /^NO_TEXT_FOUND$/i.test(rawText);

  // Strip OCR placeholder markers and non-alphanumeric characters before judging whether
  // there is enough *meaningful* text — a page that is mostly "[tidak terbaca]" filler
  // must not look long enough to pass the threshold just from bracket/punctuation noise.
  const meaningfulText = rawText
    .replace(/\[(tidak terbaca|illegible)\]/gi, '')
    .replace(/[^\p{L}\p{N}]/gu, '');

  const hasEnoughText = !noTextFound && meaningfulText.length >= MIN_TEXT;

  return { json: {
    file_id: src.file_id, file_name: src.file_name, file_category: 'IMAGE',
    content_mode: hasEnoughText ? 'text' : 'none',
    has_text: hasEnoughText,
    extraction_method: 'baseten_vision_ocr',
    text: hasEnoughText ? rawText : '',
    visual_description: '', page_count: 1,
    result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
    control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
    warnings: src.warnings || [],
  }};
});

// PERBAIKAN v4: node Decompress hanya bekerja kalau metadata binary
// punya fileExtension === 'zip'. File .docx punya fileExtension 'docx',
// sehingga node melewatkan operasi TANPA error (bug n8n #14133).
// DOCX memang benar-benar arsip ZIP, jadi cukup ganti labelnya.

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = items[i].json;
  const meta = (items[i].binary || {}).data;

  if (!meta) {
    throw new Error('Binary "data" tidak ditemukan pada file ' + (src.file_name || '?'));
  }

  const patched = Object.assign({}, meta, {
    fileName: (meta.fileName || 'document.docx').replace(/\.docx$/i, '.zip'),
    fileExtension: 'zip',
    mimeType: 'application/zip',
  });

  out.push({ json: src, binary: { data: patched } });
}
return out;

// PERBAIKAN: node Compression menyimpan nama asli di metadata binary
// (fileName / directory), BUKAN di nama binary property. Cari di keduanya.
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = $('Fan-out & Detect').itemMatching(i).json;
  const bin = items[i].binary || {};

  const candidates = Object.keys(bin).map(k => {
    const meta = bin[k] || {};
    const path = ((meta.directory ? meta.directory + '/' : '') + (meta.fileName || '')).toLowerCase();
    return { key: k, probe: (k + ' ' + path).toLowerCase() };
  });

  const hit = candidates.find(c => c.probe.includes('document.xml') && !c.probe.includes('rels'))
           || candidates.find(c => c.probe.includes('document') && c.probe.includes('xml') && !c.probe.includes('rels'));

  if (!hit) {
    out.push({ json: {
      file_id: src.file_id, file_name: src.file_name, file_category: 'WORD',
      content_mode: 'none', extraction_method: 'docx_unzip',
      text: '', visual_description: '', page_count: 0,
      status: 'failed', error_reason: 'document_xml_not_found',
      debug_binary_keys: candidates.map(c => c.probe).join(' ;; '),
      result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
      control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
      warnings: (src.warnings || []).concat('docx_structure_unexpected'),
    }});
    continue;
  }

  const buf = await this.helpers.getBinaryDataBuffer(i, hit.key);
  const xml = buf.toString('utf8');

  const text = xml
    .replace(/<w:tab\b[^>]*\/>/g, '\t')
    .replace(/<w:br\b[^>]*\/>/g, '\n')
    .replace(/<\/w:p>/g, '\n')
    .replace(/<\/w:tc>/g, ' | ')
    .replace(/<\/w:tr>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  out.push({ json: {
    file_id: src.file_id, file_name: src.file_name, file_category: 'WORD',
    content_mode: 'text', extraction_method: 'docx_unzip',
    text, visual_description: '', page_count: 1,
    result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
    control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
    warnings: (src.warnings || []).concat('formatting_not_preserved'),
  }});
}
return out;

const items = $input.all();
const out = [];

function cleanText(text) {
  return text
    .replace(/\r\n/g, '\n')
    .replace(/[\r\x0b\x0c]/g, '\n')
    .replace(/\x07/g, ' | ')
    .replace(/[\x00-\x08\x0e-\x1f]/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractTextRuns(raw) {
  const runs = [];
  let curr16 = '';
  for (let i = 0; i + 1 < raw.length; i += 2) {
    const code = raw.readUInt16LE(i);
    if ((code >= 0x20 && code <= 0x7E) || code === 0x0A || code === 0x0D || code === 0x09 || (code >= 0xA0 && code <= 0xFF)) {
      curr16 += (code === 0x0D || code === 0x0A) ? '\n' : String.fromCharCode(code);
    } else {
      if (curr16.length >= 10) runs.push(curr16);
      curr16 = '';
    }
  }
  if (curr16.length >= 10) runs.push(curr16);

  let curr8 = '';
  for (let i = 0; i < raw.length; i++) {
    const code = raw[i];
    if ((code >= 0x20 && code <= 0x7E) || code === 0x0A || code === 0x0D || code === 0x09) {
      curr8 += (code === 0x0D || code === 0x0A) ? '\n' : String.fromCharCode(code);
    } else {
      if (curr8.length >= 10) runs.push(curr8);
      curr8 = '';
    }
  }
  if (curr8.length >= 10) runs.push(curr8);

  return cleanText(runs.join('\n\n'));
}

function parseDoc(buf) {
  const magic = buf.subarray(0, 8).toString('hex').toUpperCase();
  if (!magic.startsWith('D0CF11E0')) return extractTextRuns(buf);

  try {
    const sectorSize = 1 << buf.readUInt16LE(30);
    const numFatSectors = buf.readUInt32LE(44);
    const dirFirstSector = buf.readUInt32LE(48);

    const difat = [];
    for (let i = 0; i < 109 && i < numFatSectors; i++) {
      const s = buf.readUInt32LE(76 + i * 4);
      if (s < 0xFFFFFFFA) difat.push(s);
    }

    const fat = [];
    for (const fatSec of difat) {
      const offset = (fatSec + 1) * sectorSize;
      for (let i = 0; i < sectorSize / 4; i++) fat.push(buf.readUInt32LE(offset + i * 4));
    }

    function readChain(startSec) {
      const sectors = [];
      let curr = startSec;
      while (curr < 0xFFFFFFFA && curr < fat.length) {
        sectors.push(curr);
        curr = fat[curr];
      }
      const totalBuf = Buffer.alloc(sectors.length * sectorSize);
      for (let i = 0; i < sectors.length; i++) {
        const srcOffset = (sectors[i] + 1) * sectorSize;
        buf.copy(totalBuf, i * sectorSize, srcOffset, srcOffset + sectorSize);
      }
      return totalBuf;
    }

    const dirBuf = readChain(dirFirstSector);
    const entries = [];
    for (let i = 0; i < dirBuf.length / 128; i++) {
      const e = dirBuf.subarray(i * 128, (i + 1) * 128);
      const nameLen = e.readUInt16LE(64);
      if (nameLen === 0) continue;
      const name = e.subarray(0, nameLen - 2).toString('utf16le');
      const type = e.readUInt8(66);
      const startSec = e.readUInt32LE(116);
      const size = e.readUInt32LE(120);
      entries.push({ name, type, startSec, size });
    }

    const wordDocEntry = entries.find(e => e.name === 'WordDocument');
    if (!wordDocEntry) return extractTextRuns(buf);

    const wordDocBuf = readChain(wordDocEntry.startSec).subarray(0, wordDocEntry.size);
    const flags = wordDocBuf.readUInt16LE(10);
    const use1Table = (flags & 0x0200) !== 0;
    const tableEntry = entries.find(e => e.name === (use1Table ? '1Table' : '0Table'));

    let text = '';
    if (tableEntry) {
      try {
        const tableBuf = readChain(tableEntry.startSec).subarray(0, tableEntry.size);
        const fcClx = wordDocBuf.readUInt32LE(0x01A2);
        const lcbClx = wordDocBuf.readUInt32LE(0x01A6);

        if (lcbClx > 0 && fcClx + lcbClx <= tableBuf.length) {
          const clxBuf = tableBuf.subarray(fcClx, fcClx + lcbClx);
          let pos = 0;
          while (pos < clxBuf.length) {
            const type = clxBuf.readUInt8(pos);
            pos += 1;
            if (type === 1) {
              const cbGrpprl = clxBuf.readUInt16LE(pos);
              pos += 2 + cbGrpprl;
            } else if (type === 2) {
              const cbPlcfpcd = clxBuf.readUInt32LE(pos);
              pos += 4;
              const pcdCount = (cbPlcfpcd - 4) / 12;
              const cpArray = [];
              for (let i = 0; i <= pcdCount; i++) cpArray.push(clxBuf.readUInt32LE(pos + i * 4));
              const pcdOffset = pos + (pcdCount + 1) * 4;
              for (let i = 0; i < pcdCount; i++) {
                const cpLen = cpArray[i + 1] - cpArray[i];
                const fcVal = clxBuf.readUInt32LE(pcdOffset + i * 8 + 2);
                const isCompressed = (fcVal & (1 << 30)) !== 0;
                const actualFc = (fcVal & ~(1 << 30));
                if (isCompressed) {
                  const byteOffset = Math.floor(actualFc / 2);
                  text += wordDocBuf.subarray(byteOffset, byteOffset + cpLen).toString('latin1');
                } else {
                  text += wordDocBuf.subarray(actualFc, actualFc + cpLen * 2).toString('utf16le');
                }
              }
              break;
            } else break;
          }
        }
      } catch (err) {}
    }

    if (text.length >= 50) return cleanText(text);

    const fallback = extractTextRuns(wordDocBuf);
    if (fallback.length >= 50) return fallback;

    return extractTextRuns(buf);
  } catch (err) {
    return extractTextRuns(buf);
  }
}

for (let i = 0; i < items.length; i++) {
  const src = $('Fan-out & Detect').itemMatching(i).json;
  const warnings = (src.warnings || []).slice();

  let text = '';
  let status = undefined;
  let errorReason = null;

  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    text = parseDoc(buf);
    if (!text || text.length < 50) {
      status = 'unreadable';
      errorReason = 'doc_text_insufficient';
      warnings.push('doc_text_below_threshold');
    }
  } catch (err) {
    status = 'failed';
    errorReason = 'doc_parse_error: ' + (err.message || 'unknown');
    warnings.push('doc_parse_exception');
  }

  out.push({
    json: {
      file_id: src.file_id,
      file_name: src.file_name,
      file_category: 'LEGACY_DOC',
      content_mode: (text && text.length >= 50) ? 'text' : 'none',
      extraction_method: 'legacy_doc_parser',
      text: text || '',
      visual_description: '',
      page_count: 1,
      status: status,
      error_reason: errorReason,
      result_id: src.result_id || null,
      file_path: src.file_path || null,
      locale: src.locale || 'en',
      control_code: src.control_code || '',
      control_title: src.control_title || '',
      control_requirement: src.control_requirement || '',
      warnings: warnings,
    }
  });
}
return out;

// Skema kanonik.
// text               = hasil penyalinan  (fakta di dokumen)
// visual_description = hasil pengamatan  (klaim model tentang gambar)
// content_summary    = diisi belakangan oleh cabang ringkasan
const MIN_TEXT = 50;
const MIN_DESC = 30;
const MAX_CHARS = 200000;

return $input.all().map(item => {
  const j = item.json || {};

  let text = (j.text || '').trim();
  const desc = (j.visual_description || '').trim();

  const truncated = text.length > MAX_CHARS;
  if (truncated) text = text.slice(0, MAX_CHARS);

  const charCount = text.length;
  let mode = j.content_mode || 'none';
  let status = j.status;
  let reason = j.error_reason || null;

  if (!status) {
    if (mode === 'text' && charCount >= MIN_TEXT) status = 'ok';
    else if (mode === 'visual' && desc.length >= MIN_DESC) status = 'ok';
    else {
      status = 'unreadable';
      mode = 'none';
      reason = reason || (charCount > 0 ? 'extracted_text_too_short' : 'no_content_extracted');
    }
  }

  // The Describe branch (visual-only images) already produces its own bilingual
  // content_summary/content_summary_id/content_relevance/content_relevance_id
  // upstream — preserve them here instead of wiping them out, since text-mode
  // items still get theirs from the summary branch further down the graph
  // (which overwrites these same fields when it runs).
  const describeSummaryEn = (j.content_summary || '').trim();
  const describeSummaryId = (j.content_summary_id || '').trim();
  const describeRelevanceEn = (j.content_relevance || '').trim();
  const describeRelevanceId = (j.content_relevance_id || '').trim();

  return { json: {
    file_id: j.file_id || null,
    file_name: j.file_name || null,
    file_category: j.file_category || 'UNKNOWN',
    result_id: j.result_id || null,
    file_path: j.file_path || null,
    locale: j.locale || 'en',
    control_code: j.control_code || '',
    control_title: j.control_title || '',
    control_requirement: j.control_requirement || '',
    content_mode: mode,
