    ? item.json.choices[0].message.content : '';

  let text = '';
  if (typeof raw === 'string') text = raw;
  else if (Array.isArray(raw)) text = raw.map(p => p.text || '').join('\\n');
  text = text.trim().replace(/\`\`\`json/gi, '').replace(/\`\`\`/g, '').trim();

  const parsed = extractJson(text);

  let summaryEn = '';
  if (parsed && parsed.en && parsed.en.summary) {
    summaryEn = Array.isArray(parsed.en.summary) ? parsed.en.summary.join('\\n') : String(parsed.en.summary);
    summaryEn = summaryEn.trim();
  }

  let summaryId = '';
  if (parsed && parsed.id && parsed.id.summary) {
    summaryId = Array.isArray(parsed.id.summary) ? parsed.id.summary.join('\\n') : String(parsed.id.summary);
    summaryId = summaryId.trim();
